'use strict';
const $=s=>document.querySelector(s);
const motifs=[{id:'heart',name:'Ett litet hjärta',sub:'2 färger · En fin första ruta',bg:'#e9e8d7',ink:'#d96453',tag:'FAVORITEN'},{id:'star',name:'En egen stjärna',sub:'2 färger · Lite vardagsmagi',bg:'#ece4d0',ink:'#d5aa43',tag:'ENKELT & FINT'},{id:'cat',name:'En mjuk kompis',sub:'3 färger · För kattälskaren',bg:'#e1e8e9',ink:'#658996',tag:'MJAU ♡'},{id:'flower',name:'En glad blomma',sub:'3 färger · Blommar året om',bg:'#eadfdf',ink:'#ba7691',tag:'LITEN & GLAD'}];
let state={motif:'heart',n:24,colors:3,bg:'#f4eddf',fg:'#dc6553',gaugeSt:20,gaugeRows:28,row:0,motifRow:1,view:'knit',title:'Ett litet hjärta',palette:[],grid:[],checks:[]};
let sourceImage=null,toastTimer;const letters='ABCDE';
function hex(rgb){return '#'+rgb.map(v=>Math.max(0,Math.min(255,Math.round(v))).toString(16).padStart(2,'0')).join('')}
function rgb(h){return [parseInt(h.slice(1,3),16),parseInt(h.slice(3,5),16),parseInt(h.slice(5,7),16)]}
function mix(a,b,t){return hex(rgb(a).map((v,i)=>v*(1-t)+rgb(b)[i]*t))}
function rows(){return Math.round(state.n*1.4)}
function totalRows(){return state.grid.length+8}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function starInside(x,y){const p=[];for(let i=0;i<10;i++){let a=-Math.PI/2+i*Math.PI/5,r=i%2?.18:.4;p.push([.5+Math.cos(a)*r,.49+Math.sin(a)*r])}let c=false;for(let i=0,j=9;i<10;j=i++){if((p[i][1]>y)!=(p[j][1]>y)&&x<(p[j][0]-p[i][0])*(y-p[i][1])/(p[j][1]-p[i][1])+p[i][0])c=!c}return c}
function shape(id,x,y){if(id==='heart'){x=(x-.5)*3;y=(.5-y)*3;return ((x*x+y*y-0.65)**3-x*x*y*y*y<0)?1:0}if(id==='star')return starInside(x,y)?1:0;if(id==='cat'){const ears=(y>.2&&y<.46&&((x>.19&&x<.41&&y>.2+Math.abs(x-.2)*.9)||(x>.59&&x<.81&&y>.2+Math.abs(x-.8)*.9)));const head=((x-.5)/.31)**2+((y-.53)/.28)**2<1;if(!ears&&!head)return 0;if((Math.abs(x-.38)<.035||Math.abs(x-.62)<.035)&&Math.abs(y-.51)<.035)return 2;if(Math.abs(x-.5)<.035&&Math.abs(y-.63)<.025)return 2;return 1}if(id==='flower'){if(Math.hypot(x-.5,y-.44)<.105)return 2;for(let i=0;i<6;i++){let a=Math.PI*2*i/6;if(Math.hypot(x-.5-Math.cos(a)*.18,y-.44-Math.sin(a)*.18)<.125)return 1}if(Math.abs(x-.5)<.028&&y>.65&&y<.88)return 1;return 0}return 0}
function demoGrid(id,n,h){return Array.from({length:h},(_,y)=>Array.from({length:n},(_,x)=>shape(id,(x+.5)/n,(y+.5)/h)))}
function knit(ctx,grid,palette,x,y,w,h,border=false){const r=grid.length,n=grid[0].length,cw=w/n,ch=h/r;ctx.fillStyle=palette[0];ctx.fillRect(x,y,w,h);for(let j=0;j<r;j++)for(let i=0;i<n;i++){let color=palette[grid[j][i]]||palette[0],xx=x+i*cw,yy=y+j*ch;ctx.fillStyle=mix(color,'#25372a',.15);ctx.fillRect(xx,yy,cw+.3,ch+.3);ctx.lineCap='round';ctx.lineWidth=Math.max(1,cw*.38);ctx.strokeStyle=color;ctx.beginPath();ctx.moveTo(xx+cw*.19,yy+ch*.1);ctx.quadraticCurveTo(xx+cw*.25,yy+ch*.57,xx+cw*.49,yy+ch*.87);ctx.moveTo(xx+cw*.81,yy+ch*.1);ctx.quadraticCurveTo(xx+cw*.75,yy+ch*.57,xx+cw*.51,yy+ch*.87);ctx.stroke();ctx.strokeStyle=mix(color,'#ffffff',.25);ctx.lineWidth=Math.max(.4,cw*.065);ctx.beginPath();ctx.moveTo(xx+cw*.16,yy+ch*.12);ctx.lineTo(xx+cw*.43,yy+ch*.77);ctx.moveTo(xx+cw*.76,yy+ch*.14);ctx.lineTo(xx+cw*.54,yy+ch*.75);ctx.stroke()}}
function withBorder(g){let n=g[0].length;return [...Array.from({length:4},()=>Array(n+6).fill(0)),...g.map(r=>[0,0,0,...r,0,0,0]),...Array.from({length:4},()=>Array(n+6).fill(0))]}
function demoCanvas(canvas,id,fg,bg,n=24){let c=canvas.getContext('2d');c.clearRect(0,0,canvas.width,canvas.height);knit(c,withBorder(demoGrid(id,n,Math.round(n*1.4))),[bg,fg,id==='flower'?'#e4bc55':'#344c4b'],30,30,canvas.width-60,canvas.height-60)}
function quantize(image,n,h,count){const c=document.createElement('canvas');c.width=320;c.height=320;const cx=c.getContext('2d',{willReadFrequently:true});cx.fillStyle=state.bg;cx.fillRect(0,0,320,320);const scale=300/Math.max(image.naturalWidth,image.naturalHeight),w=image.naturalWidth*scale,hh=image.naturalHeight*scale;cx.drawImage(image,(320-w)/2,(320-hh)/2,w,hh);const small=document.createElement('canvas');small.width=n;small.height=h;const s=small.getContext('2d',{willReadFrequently:true});s.drawImage(c,0,0,n,h);let data=s.getImageData(0,0,n,h).data,points=[];for(let i=0;i<data.length;i+=4)points.push([data[i],data[i+1],data[i+2]]);let centers=[rgb(state.bg)];function dist(a,b){return a.reduce((v,z,i)=>v+(z-b[i])**2,0)}while(centers.length<count){let far=points.reduce((best,p)=>Math.min(...centers.map(c=>dist(p,c)))>Math.min(...centers.map(c=>dist(best,c)))?p:best,points[0]);centers.push([...far])}for(let k=0;k<10;k++){let sums=centers.map(()=>[0,0,0,0]);for(const p of points){let idx=centers.map(c=>dist(c,p)).reduce((a,v,i,arr)=>v<arr[a]?i:a,0);p.forEach((v,j)=>sums[idx][j]+=v);sums[idx][3]++}centers=centers.map((c,i)=>i&&sums[i][3]?sums[i].slice(0,3).map(v=>v/sums[i][3]):c)}const palette=centers.map(hex);palette[0]=state.bg;const grid=Array.from({length:h},(_,y)=>Array.from({length:n},(_,x)=>{const p=points[y*n+x];return centers.map(c=>dist(c,p)).reduce((a,v,i,arr)=>v<arr[a]?i:a,0)}));return {grid,palette}}
function regenerate(){state.n=+$('#size').value;state.colors=+$('#colors').value;state.bg=$('#bgColor').value;state.fg=$('#fgColor').value;state.gaugeSt=+$('#gaugeSt').value;state.gaugeRows=+$('#gaugeRows').value;if(sourceImage){const q=quantize(sourceImage,state.n,rows(),state.colors);state.grid=q.grid;state.palette=q.palette}else{state.grid=demoGrid(state.motif,state.n,rows());state.palette=[state.bg,state.fg];if(state.motif==='cat'||state.motif==='flower'){if(state.colors>2)state.palette.push(state.motif==='cat'?'#354e4c':'#e8b950');else state.grid=state.grid.map(r=>r.map(v=>Math.min(v,1)))}}state.row=0;state.motifRow=1;state.checks=[];$('#colorCount').textContent='Upp till '+state.colors;render();if(!$('#pattern').hidden)buildInstructions()}
function chartCanvas(canvas) {
  const grid = state.grid;
  const columns = grid[0].length;
  const height = grid.length;
  // Keep the largest chart within a 4096 px canvas on mobile browsers.
  const compact = columns > 64;
  const cellWidth = compact ? 12 : 18;
  const cellHeight = compact ? 9 : 14;
  const margin = 34;
  const chartWidth = columns * cellWidth;
  const chartHeight = height * cellHeight;
  canvas.width = chartWidth + margin * 2;
  canvas.height = chartHeight + margin * 2;

  const ctx = canvas.getContext('2d');
  const textColors = state.palette.map(color => {
    const brightness = rgb(color).reduce((sum, channel) => sum + channel, 0);
    return brightness > 420 ? '#26392e' : 'white';
  });

  ctx.fillStyle = '#fffdf7';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.font = compact ? '7px sans-serif' : '9px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.strokeStyle = '#293d3430';
  ctx.lineWidth = .5;

  for (let row = 0; row < height; row++) {
    const y = margin + row * cellHeight;
    for (let column = 0; column < columns; column++) {
      const colorIndex = grid[row][column];
      const x = margin + column * cellWidth;
      ctx.fillStyle = state.palette[colorIndex];
      ctx.fillRect(x, y, cellWidth, cellHeight);
      ctx.strokeRect(x, y, cellWidth, cellHeight);
      ctx.fillStyle = textColors[colorIndex];
      ctx.fillText(letters[colorIndex], x + cellWidth / 2, y + cellHeight / 2);
    }
    ctx.fillStyle = '#293d34';
    ctx.fillText(height - row, margin + chartWidth + 17, y + cellHeight / 2);
  }
  for (let column = 0; column < columns; column++) {
    const x = margin + column * cellWidth + cellWidth / 2;
    ctx.fillText(columns - column, x, margin + chartHeight + 16);
  }
  ctx.textAlign = 'left';
  ctx.fillText('Motiv · 1 ruta = 1 maska · börja nere till höger', margin, 15);
}
function render(){const canvas=$('#preview');if(state.view==='grid'){chartCanvas(canvas)}else{canvas.width=700;canvas.height=700;let ctx=canvas.getContext('2d');ctx.clearRect(0,0,700,700);knit(ctx,withBorder(state.grid),state.palette,40,40,620,620)}$('#knitView').classList.toggle('active',state.view==='knit');$('#gridView').classList.toggle('active',state.view==='grid');$('#knitView').setAttribute('aria-pressed',state.view==='knit');$('#gridView').setAttribute('aria-pressed',state.view==='grid');$('#fgLabel').hidden=state.motif==='custom';$('#patternTitle').textContent=state.title;$('#chartNote').textContent=state.view==='knit'?'Så kan det se ut i garn. Färgerna är ungefärliga.':'Läs nedifrån och upp. Kolumn 1 är längst till höger. Kanten ingår inte.';$('#legend').replaceChildren();state.palette.forEach((c,i)=>{let el=document.createElement('span'),dot=document.createElement('i');dot.style.background=c;el.append(dot,document.createTextNode(letters[i]+(i===0?' · bottenfärg':' · motivfärg')));$('#legend').append(el)});document.querySelectorAll('.motif-card').forEach(c=>c.classList.toggle('selected',c.dataset.id===state.motif))}
function pickMotif(m,scroll=true){sourceImage=null;state.motif=m.id;state.title=m.name;$('#fgColor').value=m.ink;$('#colors').value=(m.id==='cat'||m.id==='flower')?3:2;$('#fileStatus').textContent='';$('#upload').value='';regenerate();if(scroll)$('#studio').scrollIntoView({behavior:'smooth'})}
function initCards(){const root=$('#motifCards');motifs.forEach(m=>{const b=document.createElement('button');b.type='button';b.className='motif-card';b.dataset.id=m.id;b.innerHTML=`<div class="card-image" style="background:${m.bg}"><span class="tag">${m.tag}</span><canvas width="360" height="360" aria-label="${m.name}"></canvas></div><div class="card-label"><div><h3>${m.name}</h3><p>${m.sub}</p></div><b aria-hidden="true">↗</b></div>`;b.addEventListener('click',()=>pickMotif(m));root.append(b);demoCanvas(b.querySelector('canvas'),m.id,m.ink,'#f5f0e4')})}
function validGauge(){return Number.isFinite(state.gaugeSt)&&state.gaugeSt>=8&&state.gaugeSt<=50&&Number.isFinite(state.gaugeRows)&&state.gaugeRows>=10&&state.gaugeRows<=70}
function buildInstructions(){if(!validGauge()){toast('Ange 8–50 maskor och 10–70 varv per 10 cm.');return false}const n=state.n,h=state.grid.length,t=totalRows(),width=((n+6)/state.gaugeSt*10).toFixed(1).replace('.',','),height=(t/state.gaugeRows*10).toFixed(1).replace('.',',');$('#instructionTitle').textContent=state.title+' — steg för steg.';$('#metrics').innerHTML=`<div class="metric"><strong>${n+6}</strong><span>maskor att lägga upp</span></div><div class="metric"><strong>${t}</strong><span>varv före avmaskning</span></div><div class="metric"><strong>${width} × ${height}</strong><span>cm, ungefär · med kant</span></div><div class="metric"><strong>${state.palette.length}</strong><span>garnfärger totalt</span></div>`;const mats=[`Ett par stickor, cirka 4–5 mm. Anpassa till garnets banderoll.`,`Slätt garn: ${n>32?'välj mängd i bottenfärg A utifrån en vägd provlapp och rutans mått':'cirka 25–50 g i bottenfärg A'} och ${n>64?'garn i':'små rester i'} motivfärgerna ${state.palette.slice(1).map((_,i)=>letters[i+1]).join(', ')}. Använd samma garntjocklek.`,`En trubbig garnnål och en sax.`,`Provlapp: ${state.gaugeSt} maskor och ${state.gaugeRows} varv = 10 × 10 cm i slätstickning. Storleken är ungefärlig eftersom kanten är rätstickad.`];$('#materials').replaceChildren();mats.forEach((m,i)=>{let l=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=!!state.checks[i];check.addEventListener('change',()=>{state.checks[i]=check.checked});l.append(check,document.createTextNode(m));$('#materials').append(l)});const instructions=[['Lägg upp maskorna',`Lägg upp ${n+6} maskor i bottenfärg A. Räkna en gång extra. Vi gör en platt ruta som kan bli ett litet underlägg eller en lapp att sy på en väska. <a href="#learn">Se hjälp med uppläggningen ↓</a>`],['Sticka kanten längst ner',`Sticka varv 1–4 med bara räta maskor, ${n+6} maskor på varje varv. Vänd efter varje varv. Kanten blir rätstickad och hjälper rutan att hålla formen.`],['Sticka själva rutan',`Sticka varv 5–${h+4}, totalt ${h} varv, i bottenfärg A. På udda varv (framsidan): sticka alla ${n+6} maskor räta. På jämna varv (baksidan): sticka 3 räta, ${n} aviga och 3 räta. Vänd efter varje varv. Flytta garnet mellan stickspetsarna när du byter mellan räta och aviga. De tre maskorna på varje sida är kant; mitten blir slätstickad.`],['Gör den sista kanten',`Sticka varv ${h+5}–${t} med bara räta maskor. Avmaska sedan löst på nästa varv. Klipp garnet med cirka 15 cm kvar, dra änden genom sista öglan och fäst på baksidan.`],['Sy dit ditt motiv',`Lägg rutan med V-sidan uppåt. Diagrammet visar bara mitten: ${n} maskor × ${h} varv. Lämna de 3 kantmaskorna på varje sida och de 4 kantvarven upptill och nedtill fria. Börja vid rad 1, kolumn 1: den första motivmaskan direkt ovanför nedre kanten och innanför höger kant. En ruta i diagrammet motsvarar ett stickat V. A är bottenfärg och behöver inte sys. Följ radguiden och sy B${state.palette.length>2?' och övriga motivfärger':''} med maskstygn, en färg i taget. <a href="#learn">Så syr du maskstygn ↓</a>`],['Fäst trådarna — och var stolt!',`Fäst garnändarna på baksidan genom att väva dem genom flera maskor och tillbaka åt andra hållet. Klipp bort överflödigt garn. Fukta försiktigt enligt garnets tvättråd och låt rutan torka plant om du vill jämna till den. Nu har du skapat något alldeles eget!`]];$('#steps').innerHTML=instructions.map((s,i)=>`<details open><summary><span>${i+1}</span>${s[0]}</summary><p>${s[1]}</p></details>`).join('');const c=document.createElement('canvas');chartCanvas(c);$('#printChart').src=c.toDataURL('image/png');$('#printLegend').textContent=state.palette.map((p,i)=>`${letters[i]} = ${p}${i===0?' (bottenfärg, sys inte)':''}`).join(' · ')+`. Motivet är ${n} maskor × ${h} varv. Kanten ingår inte i diagrammet. Rad 1 är nederst, kolumn 1 till höger.`;updateProgress();updateMotifRow();return true}
function updateProgress(){const t=totalRows();state.row=Math.max(0,Math.min(t,state.row));$('#rowCount').textContent=state.row;$('#rowTotal').textContent='av '+t+' varv klara';$('#rowProgress').max=t;$('#rowProgress').value=state.row;$('#minus').disabled=state.row===0;$('#plus').disabled=state.row===t;let next=state.row+1;let s=state.row===t?'Alla varv är klara! Avmaska, fäst bottenfärgens trådar och sy sedan motivet.':next<=4||next>state.grid.length+4?`Nästa: varv ${next}. Sticka alla ${state.n+6} maskor räta.`:next%2?`Nästa: varv ${next}, framsidan. Sticka alla ${state.n+6} maskor räta.`:`Nästa: varv ${next}, baksidan. 3 räta, ${state.n} aviga, 3 räta.`;$('#rowHelp').textContent=s}
function updateMotifRow(){const h=state.grid.length;state.motifRow=Math.max(1,Math.min(h,state.motifRow));$('#motifRowLabel').textContent='Rad '+state.motifRow+' av '+h;$('#motifMinus').disabled=state.motifRow===1;$('#motifPlus').disabled=state.motifRow===h;const r=[...state.grid[h-state.motifRow]].reverse(),runs=[];r.forEach((v,i)=>{if(i&&runs.at(-1).v===v)runs.at(-1).end=i+1;else runs.push({v,start:i+1,end:i+1})});const root=$('#rowInstructions');root.replaceChildren();runs.forEach(run=>{const div=document.createElement('div'),i=document.createElement('i');i.style.background=state.palette[run.v];div.append(i,document.createTextNode(`Kol. ${run.start}${run.end>run.start?'–'+run.end:''}: ${letters[run.v]}${run.v===0?' · hoppa över':' · sy '+(run.end-run.start+1)+' mask'+(run.end===run.start?'a':'or')}`));root.append(div)})}
async function loadImage(file){if(!file)return;if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)){toast('Välj en JPG-, PNG-, WebP- eller GIF-bild.');return}if(file.size>12*1024*1024){toast('Bilden är för stor. Välj en bild under 12 MB.');return}const url=URL.createObjectURL(file),im=new Image();im.onload=()=>{sourceImage=im;state.motif='custom';state.title='Mitt eget bildmotiv';$('#fileStatus').textContent='✓ '+file.name;regenerate();URL.revokeObjectURL(url);toast('Din bild har blivit ett färgdiagram!')};im.onerror=()=>{URL.revokeObjectURL(url);toast('Bilden gick inte att läsa. Prova en annan bild.')};im.src=url}
function saveProject(){try{localStorage.setItem('maska-project-v1',JSON.stringify({...state,view:'knit'}));toast('Projektet är sparat i den här webbläsaren ♡')}catch{toast('Det gick inte att spara. Webbläsarens lagring kan vara full.')}}
function restoreProject(){try{const s=JSON.parse(localStorage.getItem('maska-project-v1'));if(!s||![16,24,32,64,248].includes(s.n)||!Array.isArray(s.grid)||s.grid.length!==Math.round(s.n*1.4)||!s.grid.every(r=>Array.isArray(r)&&r.length===s.n&&r.every(v=>Number.isInteger(v)&&v>=0&&v<s.palette.length))||!Array.isArray(s.palette)||s.palette.length<2||s.palette.length>5||!s.palette.every(p=>/^#[0-9a-f]{6}$/i.test(p)))return false;state={...state,...s,title:s.motif==='custom'?'Mitt eget bildmotiv':(motifs.find(m=>m.id===s.motif)?.name||'Mitt sparade motiv'),checks:Array.isArray(s.checks)?s.checks:[],view:'knit'};$('#size').value=state.n;$('#colors').value=state.colors;$('#bgColor').value=state.bg;$('#fgColor').value=state.fg;$('#gaugeSt').value=state.gaugeSt;$('#gaugeRows').value=state.gaugeRows;$('#colorCount').textContent='Upp till '+state.colors;render();buildInstructions();$('#pattern').hidden=false;if(state.motif==='custom'){$('#fileStatus').textContent='✓ Sparat bildmotiv återställt. Ladda upp bilden igen om du vill ändra upplösning eller färgantal.'}toast('Välkommen tillbaka! Ditt projekt finns kvar ♡');return true}catch{return false}}
